-- 멘헤라(운영자 승인, 후보 검수 통과) + 에겐/테토(운영자 직접 지시) 추가 (2026-09-06).
--
-- 멘헤라: draft_payload 그대로 승격. category=slang(성인 게이트) 유지 — 실제 정신질환자에
-- 대한 낙인성 표현이라 운영자가 slang으로 확정. 어원(일본 2ch メンヘラー)은 독립 출처 4개 일치,
-- 한국 유입 시점(2017년경)은 1차 자료가 없어 '전해진다' 수준으로만 서술.
--
-- 에겐/테토: 표제어는 기본형 2개로 두고 성별 파생형(에겐남/에겐녀, 테토남/테토녀)은 aliases로 처리.
-- 어원 검증: 에스트로겐/테스토스테론 축약. 2021년 블로그 원형설 → 2024-03 인스타툰 재구성 →
-- 2025년 중반 대유행(한국경제·데일리웰니스·나무위키·핸드메이커 일치). 최초 출처는 확정되지 않아
-- 확정 표기하지 않는다. 실제 호르몬 수치와 과학적 연관 없음, 성 이분법 비판 존재 — 본문에 명시.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations, aliases) values
('270', '멘헤라', 'Men-He-Ra', 'slang', '정서가 불안하고 집착이 심한 사람을 가리키는 낙인성 표현', '{"de": "Ein stigmatisierendes Etikett für emotional instabile, klammernde Menschen", "en": "A stigmatizing label for someone emotionally unstable and clingy", "es": "Etiqueta estigmatizante para alguien inestable y obsesivo", "ja": "情緒不安定で執着が強い人を指す、烙印的な表現", "vi": "Nhãn dán kỳ thị chỉ người bất ổn cảm xúc và bám dính"}'::jsonb, '[멘헤라]', '[{"type": "명사", "examples": [{"de": "In der Beziehung hab ich alles runtergeschluckt, nur um nicht als klammernd zu gelten.", "es": "En esa relación me tragué todo lo que me dolía solo para que no me llamaran dependiente.", "ja": "付き合ってるとき、メンヘラって言われたくなくて寂しさを全部我慢してた。", "vi": "Lúc yêu, mình nín hết mọi tủi thân chỉ vì không muốn bị gọi là bám dính.", "eng": "I bottled up everything that hurt me in that relationship just so I would not be called clingy.", "kor": "연애할 때 멘헤라 소리 듣기 싫어서 서운한 거 다 참았어."}, {"de": "Jemanden „Menhera“ zu nennen, weil es ihm schlecht geht, ist doch nicht okay, oder?", "es": "Llamar “menhera” a alguien porque lo está pasando mal no está bien, ¿no?", "ja": "人がしんどいのを見てメンヘラって言うのは違うくない?", "vi": "Thấy người ta đang khổ mà gọi là “menhera” thì đâu có được, nhỉ?", "eng": "Calling someone “menhera” because they are struggling is not okay, is it?", "kor": "남 힘든 거 보고 멘헤라라고 하는 건 좀 아니지 않아?"}], "definition": "정서가 불안정하고 애정결핍·집착이 심한 사람을 가리키는 일본 인터넷 은어. 원래 우울증·경계성 인격장애 등 정신질환자에 대한 고정관념에서 나온 말이며, 인터넷에서 쓰이며 ‘잘 삐지는 사람’ 정도로 뜻이 넓어졌다. 실제 질환을 겪는 사람을 낙인찍는 표현이므로 사용에 주의가 필요하다.", "definition_i18n": {"de": "Ein japanischer Internetbegriff für emotional instabile, klammernde und zuwendungsbedürftige Menschen. Er entstand aus Klischees über Depression und Borderline und bedeutet online inzwischen auch bloß „jemand, der schnell schmollt“. Da er real Erkrankte stigmatisiert, ist Vorsicht geboten.", "en": "A Japanese internet term for someone emotionally unstable, clingy and starved for affection. It grew out of stereotypes about depression and borderline personality disorder, and online it has widened to mean roughly “someone who sulks easily.” Because it stigmatizes people with real conditions, use it with care.", "es": "Término de internet japonés para alguien emocionalmente inestable, dependiente y necesitado de afecto. Nació de estereotipos sobre la depresión y el trastorno límite de la personalidad, y en línea se ha ampliado hasta significar “alguien que se enfada por nada”. Estigmatiza a personas con trastornos reales, así que conviene usarlo con cuidado.", "ja": "情緒不安定で愛情不足・執着が強い人を指す日本のネットスラング。もともとうつ病や境界性人格障害などの精神疾患者への固定観念から生まれた語で、ネット上では「すぐ拗ねる人」程度にまで意味が広がった。実際に疾患のある人を烙印づける表現なので使用には注意が必要。", "vi": "Tiếng lóng mạng Nhật chỉ người bất ổn cảm xúc, thiếu thốn tình cảm và hay bám dính. Từ này sinh ra từ định kiến về trầm cảm và rối loạn nhân cách ranh giới, trên mạng đã nới rộng thành “người dễ hờn dỗi”. Vì nó dán nhãn kỳ thị lên người có bệnh thật nên cần dùng thận trọng."}}]'::jsonb, '일본 2ch의 정신건강(메ン탈헬스) 게시판에 있을 법한 사람이라는 뜻으로 ‘멘탈 헬스’에 영어 -er을 붙인 ‘メンヘラー’가 기원으로 알려져 있다. 한국에는 2017년 무렵 서브컬처 경로로 들어와 트위터의 이른바 ‘우울계’ 등에서 쓰이기 시작했다고 전해지나, 유입 시점을 뒷받침하는 1차 자료는 확인되지 않는다.', '{"de": "Meist auf メンヘラー im japanischen 2ch zurückgeführt: „mental health“ plus englisches -er, also jemand vom Psychiatrie-Board. Es soll um 2017 über Subkultur-Kanäle nach Korea gekommen und in den sogenannten Depressions-Accounts auf Twitter verbreitet worden sein, doch eine Primärquelle für dieses Datum fehlt.", "en": "It is generally traced to メンヘラー on Japan’s 2ch — “mental health” plus the English -er, meaning someone who belongs on the mental-health board. It is said to have entered Korea around 2017 through subculture channels and spread among the so-called depression communities on Twitter, though no primary source confirms that date.", "es": "Suele remontarse a メンヘラー en el 2ch japonés: “salud mental” más el sufijo inglés -er, es decir, alguien del foro de salud mental. Se dice que llegó a Corea hacia 2017 por vías de la subcultura y se extendió por las llamadas cuentas depresivas de Twitter, pero ninguna fuente primaria confirma esa fecha.", "ja": "日本の2ch「メンタルヘルス板にいそうな人」の意で「メンタルヘルス」に英語の-erを付けた「メンヘラー」が起源とされる。韓国へは2017年ごろサブカルチャー経由で入り、Twitterのいわゆる「鬱垢」界隈で使われ始めたと伝えられるが、時期を裏づける一次資料は確認できない。", "vi": "Thường được truy về メンヘラー trên 2ch Nhật: “mental health” cộng hậu tố -er, tức người hay ở diễn đàn sức khỏe tâm thần. Nghe nói nó vào Hàn khoảng 2017 qua ngả subculture rồi lan trong các tài khoản trầm cảm trên Twitter, nhưng không có nguồn gốc nào xác nhận mốc thời gian đó."}'::jsonb, '연애·인간관계 이야기에서 상대를 깎아내릴 때 쓰이는 경우가 많아, 남을 가리켜 쓰면 명백한 비하가 된다. 자조적으로 자신에게 쓰는 사람도 있지만, 정신건강을 놀림거리로 삼는 표현이라는 비판이 꾸준하다. 외국인 학습자는 뜻만 알아 두고 직접 쓰지 않기를 권한다.', '{"de": "Meist benutzt, um jemanden in Beziehungsgesprächen abzuwerten — auf andere gemünzt ist es klar herabwürdigend. Manche verwenden es selbstironisch, doch es steht in der Dauerkritik, psychische Gesundheit zur Pointe zu machen. Lernenden sei geraten, es zu kennen, nicht zu benutzen.", "en": "Most often used to put someone down in talk about relationships, so aiming it at another person is plainly derogatory. Some use it self-deprecatingly, but it draws steady criticism for making mental health a punchline. Learners are advised to recognize it, not use it.", "es": "Se emplea sobre todo para menospreciar a alguien al hablar de relaciones, así que dirigirlo a otra persona es claramente despectivo. Hay quien lo usa consigo mismo con autoironía, pero recibe críticas constantes por convertir la salud mental en chiste. A los estudiantes se les recomienda reconocerlo, no usarlo.", "ja": "恋愛や人間関係の話で相手を貶めるときに使われることが多く、他人に向ければ明確な侮蔑になる。自嘲的に自分へ使う人もいるが、精神の健康を笑いものにする表現だという批判が絶えない。学習者は意味を知るにとどめ、自分では使わないことを勧める。", "vi": "Thường dùng để hạ thấp ai đó khi nói chuyện yêu đương, nên nhắm vào người khác là rõ ràng miệt thị. Một số người tự trào dùng cho chính mình, nhưng từ này liên tục bị chỉ trích vì biến sức khỏe tâm thần thành trò cười. Người học nên biết nghĩa chứ đừng dùng."}'::jsonb, array['관종','현타','마상'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Menhera (emotionally unstable, clingy) — derogatory"}, {"lang": "🇯🇵 JA", "text": "メンヘラ(情緒不安定)※侮蔑的"}, {"lang": "🇨🇳 ZH", "text": "精神不稳定、黏人的人(贬义)"}, {"lang": "🇻🇳 VI", "text": "Người bất ổn cảm xúc, bám dính (miệt thị)"}, {"lang": "🇪🇸 ES", "text": "Menhera (inestable y dependiente) — despectivo"}, {"lang": "🇩🇪 DE", "text": "Menhera (labil, klammernd) — abwertend"}]'::jsonb, array[]::text[]),
('271', '에겐', 'E-Gen', 'new-slang', '여성호르몬 에스트로겐에 빗댄 성격 유형. 섬세하고 감성적인 쪽', '{"en": "A personality type named after estrogen — the sensitive, emotionally attuned side", "ja": "女性ホルモン「エストロゲン」に例えた性格タイプ。繊細で感性的な方", "es": "Tipo de personalidad bautizado por el estrógeno: el lado sensible y emocional", "vi": "Kiểu tính cách đặt theo estrogen — bên nhạy cảm, thiên về cảm xúc", "de": "Ein nach Östrogen benannter Persönlichkeitstyp — die feinfühlige, emotionale Seite"}'::jsonb, '[에겐]', '[{"type": "명사", "definition": "여성호르몬 에스트로겐(estrogen)의 앞 글자를 딴 말로, 부드럽고 섬세하며 감정 표현이 조심스러운 성격 유형. 성별을 붙여 ‘에겐남’(감성적이고 배려심 많은 남자), ‘에겐녀’(눈치가 빠르고 갈등을 피하는 여자)로 쓴다. 실제 호르몬 수치와는 과학적 관련이 없는 재미 위주의 분류다.", "definition_i18n": {"en": "From the first syllables of “estrogen”: a personality type that is gentle, sensitive and cautious about showing feelings. Add a gender marker for 에겐남 (a soft, considerate guy) or 에겐녀 (a woman who reads the room and avoids conflict). It has no scientific link to actual hormone levels — it is a for-fun classification.", "ja": "女性ホルモン「エストロゲン」の頭を取った語で、柔らかく繊細で感情表現が控えめな性格タイプ。性別を付けて「에겐남」(感性的で思いやりのある男性)、「에겐녀」(空気を読み対立を避ける女性)と使う。実際のホルモン値とは科学的な関係がない、遊び半分の分類。", "es": "De las primeras sílabas de “estrógeno”: un tipo de personalidad suave, sensible y prudente al mostrar emociones. Con marca de género da 에겐남 (un chico delicado y atento) o 에겐녀 (una mujer que lee el ambiente y evita el conflicto). No tiene relación científica con los niveles hormonales reales; es una clasificación lúdica.", "vi": "Lấy âm đầu của “estrogen”: kiểu tính cách dịu dàng, nhạy cảm, dè dặt khi bộc lộ cảm xúc. Thêm giới tính thành 에겐남 (chàng trai mềm mỏng, chu đáo) hay 에겐녀 (cô gái tinh ý, tránh xung đột). Không có liên hệ khoa học với nồng độ hormone thật — chỉ là cách phân loại cho vui.", "de": "Von den ersten Silben von „Östrogen“: ein Persönlichkeitstyp, der sanft und feinfühlig ist und Gefühle vorsichtig zeigt. Mit Geschlechtsangabe wird daraus 에겐남 (ein weicher, rücksichtsvoller Typ) oder 에겐녀 (eine Frau, die die Stimmung liest und Streit meidet). Wissenschaftlich hat das nichts mit echten Hormonwerten zu tun — es ist eine Spaßeinteilung."}, "examples": [{"kor": "나 완전 에겐남이라 갈등 생기면 그냥 참아.", "eng": "I am such an egen guy — when there is friction I just swallow it.", "ja": "僕は完全に에겐남だから、もめると黙って我慢しちゃう。", "es": "Soy totalmente un chico egen: si hay roce, me lo trago y ya.", "vi": "Mình đúng kiểu egen luôn — có xích mích là chỉ nín nhịn.", "de": "Ich bin voll der Egen-Typ — bei Reibereien schlucke ich es einfach runter."}, {"kor": "테스트 해봤는데 에겐녀 나왔어. 맞는 것 같아?", "eng": "I took the test and got egen-nyeo. Does that sound like me?", "ja": "テストしたら에겐녀だった。合ってると思う?", "es": "Hice el test y me salió egen-nyeo. ¿Me pega?", "vi": "Mình làm test ra egen-nyeo. Thấy giống mình không?", "de": "Ich habe den Test gemacht und Egen-nyeo bekommen. Passt das zu mir?"}]}]'::jsonb, '여성호르몬 에스트로겐(estrogen)의 축약. 남성호르몬을 딴 ‘테토’와 짝을 이루는 성격 유형 분류로, 2021년 블로그 글에서 비슷한 분류가 처음 제시됐다는 설이 있고 2024년 3월 인스타툰으로 재구성돼 퍼진 뒤 2025년 중반 ‘에겐남·테토녀’ 형태로 크게 유행했다. 최초 출처는 확정되지 않았다.', '{"en": "Short for the hormone estrogen. It pairs with 테토 (from testosterone) as a personality classification: a 2021 blog post is credited with an early version, an Instagram webtoon reworked it in March 2024, and the 에겐남/테토녀 labels went mainstream around mid-2025. The first source is not settled.", "ja": "女性ホルモン「エストロゲン」の略。男性ホルモン由来の「테토」と対になる性格分類で、2021年のブログ記事に原型があるとされ、2024年3月にインスタ漫画で再構成されて広まり、2025年半ばに「에겐남・테토녀」の形で大流行した。最初の出典は未確定。", "es": "Abreviatura de la hormona estrógeno. Forma pareja con 테토 (de testosterona) como clasificación de personalidad: se atribuye una versión temprana a un blog de 2021, un webtoon de Instagram la rehízo en marzo de 2024 y las etiquetas 에겐남/테토녀 estallaron hacia mediados de 2025. La fuente original no está confirmada.", "vi": "Viết tắt của hormone estrogen. Đi cặp với 테토 (từ testosterone) thành một cách phân loại tính cách: một bài blog năm 2021 được cho là bản đầu, webtoon Instagram dựng lại tháng 3/2024, rồi các nhãn 에겐남/테토녀 bùng lên giữa năm 2025. Nguồn đầu tiên chưa được xác định.", "de": "Kurzform des Hormons Östrogen. Es bildet mit 테토 (von Testosteron) ein Paar als Persönlichkeitsschema: Eine frühe Fassung wird einem Blogbeitrag von 2021 zugeschrieben, ein Instagram-Webtoon arbeitete sie im März 2024 neu auf, und die Label 에겐남/테토녀 wurden Mitte 2025 zum Massentrend. Die Erstquelle ist ungeklärt."}'::jsonb, '‘에겐남’, ‘에겐녀’처럼 성별을 붙여 쓰고, 온라인 성향 테스트 결과를 공유하며 MBTI처럼 가볍게 쓴다. 어느 형태로 검색해도 이 항목 하나로 나온다. 다만 성격을 남녀 호르몬으로 가르는 방식이라 성 고정관념을 굳힌다는 비판도 있어, 남을 규정하기보다 자기 소개용으로 쓰는 편이 무난하다.', '{"en": "Used with a gender marker — 에겐남, 에겐녀 — and traded around like MBTI results from online quizzes; either form leads to this one entry. Note that sorting personality by male/female hormones draws criticism for reinforcing gender stereotypes, so it lands better as self-description than as a label for others.", "ja": "「에겐남」「에겐녀」のように性別を付けて使い、オンライン診断の結果をMBTIのように気軽に共有する。どちらの形で検索してもこの一項目にたどり着く。ただし性格を男女のホルモンで分ける発想は性別の固定観念を強めるという批判もあるため、他人を決めつけるより自己紹介に使うのが無難。", "es": "Se usa con marca de género — 에겐남, 에겐녀 — y se comparte como los resultados de MBTI en tests en línea; cualquiera de las formas lleva a esta misma entrada. Ojo: clasificar la personalidad por hormonas masculinas y femeninas recibe críticas por reforzar estereotipos de género, así que funciona mejor para describirse a uno mismo que para etiquetar a otros.", "vi": "Dùng kèm giới tính — 에겐남, 에겐녀 — và chia sẻ kết quả trắc nghiệm online y như MBTI; tìm dạng nào cũng ra đúng mục này. Lưu ý: chia tính cách theo hormone nam/nữ bị phê là củng cố định kiến giới, nên dùng để tự giới thiệu thì ổn hơn là gán cho người khác.", "de": "Wird mit Geschlechtsangabe benutzt — 에겐남, 에겐녀 — und wie MBTI-Ergebnisse aus Online-Tests herumgereicht; beide Formen führen zu diesem einen Eintrag. Achtung: Persönlichkeit nach männlichen und weiblichen Hormonen zu sortieren, steht in der Kritik, Geschlechterklischees zu verfestigen — als Selbstbeschreibung passt es besser als als Etikett für andere."}'::jsonb, array['테토'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "“Egen” — the estrogen (soft, sensitive) personality type"}, {"lang": "🇯🇵 JA", "text": "エゲン(エストロゲン型・繊細で優しいタイプ)"}, {"lang": "🇨🇳 ZH", "text": "雌激素型性格(细腻感性)"}, {"lang": "🇻🇳 VI", "text": "Kiểu “estrogen” — dịu dàng, nhạy cảm"}, {"lang": "🇪🇸 ES", "text": "“Egen” — tipo estrógeno (suave y sensible)"}, {"lang": "🇩🇪 DE", "text": "„Egen“ — der Östrogen-Typ (sanft, feinfühlig)"}]'::jsonb, array['에겐남','에겐녀']),
('272', '테토', 'Te-To', 'new-slang', '남성호르몬 테스토스테론에 빗댄 성격 유형. 직진하고 주도적인 쪽', '{"en": "A personality type named after testosterone — the direct, take-charge side", "ja": "男性ホルモン「テストステロン」に例えた性格タイプ。直進的で主導的な方", "es": "Tipo de personalidad bautizado por la testosterona: el lado directo y dominante", "vi": "Kiểu tính cách đặt theo testosterone — bên thẳng thắn, chủ động", "de": "Ein nach Testosteron benannter Persönlichkeitstyp — die direkte, führende Seite"}'::jsonb, '[테토]', '[{"type": "명사", "definition": "남성호르몬 테스토스테론(testosterone)의 앞 글자를 딴 말로, 솔직하고 주도적이며 갈등을 피하지 않는 성격 유형. 성별을 붙여 ‘테토남’(자신감 있고 앞장서는 남자), ‘테토녀’(직설적이고 정면 돌파하는 여자)로 쓴다. 실제 호르몬 수치와는 과학적 관련이 없는 재미 위주의 분류다.", "definition_i18n": {"en": "From the first syllables of “testosterone”: a personality type that is blunt, takes the lead and does not dodge conflict. Add a gender marker for 테토남 (a confident guy who goes first) or 테토녀 (a woman who says it straight and meets things head-on). It has no scientific link to actual hormone levels — it is a for-fun classification.", "ja": "男性ホルモン「テストステロン」の頭を取った語で、率直で主導的、対立を避けない性格タイプ。性別を付けて「테토남」(自信があり前に出る男性)、「테토녀」(ストレートに言い正面突破する女性)と使う。実際のホルモン値とは科学的な関係がない、遊び半分の分類。", "es": "De las primeras sílabas de “testosterona”: un tipo de personalidad franco, que lleva la iniciativa y no esquiva el conflicto. Con marca de género da 테토남 (un chico seguro que va delante) o 테토녀 (una mujer directa que va de frente). No tiene relación científica con los niveles hormonales reales; es una clasificación lúdica.", "vi": "Lấy âm đầu của “testosterone”: kiểu tính cách thẳng thắn, chủ động, không né xung đột. Thêm giới tính thành 테토남 (chàng trai tự tin, xông xáo) hay 테토녀 (cô gái nói thẳng, đối mặt trực diện). Không có liên hệ khoa học với nồng độ hormone thật — chỉ là cách phân loại cho vui.", "de": "Von den ersten Silben von „Testosteron“: ein Persönlichkeitstyp, der direkt ist, die Führung übernimmt und Konflikten nicht ausweicht. Mit Geschlechtsangabe wird daraus 테토남 (ein selbstbewusster Typ, der vorangeht) oder 테토녀 (eine Frau, die klar sagt, was Sache ist). Wissenschaftlich hat das nichts mit echten Hormonwerten zu tun — es ist eine Spaßeinteilung."}, "examples": [{"kor": "우리 팀장님 완전 테토녀야. 할 말은 다 해.", "eng": "Our team lead is a total teto woman — she says exactly what she thinks.", "ja": "うちのチーム長、完全に테토녀。言いたいことは全部言う。", "es": "Mi jefa es totalmente teto: dice justo lo que piensa.", "vi": "Sếp mình đúng kiểu teto luôn — nghĩ gì nói nấy.", "de": "Unsere Teamleiterin ist voll der Teto-Typ — sie sagt genau, was sie denkt."}, {"kor": "테토남인 줄 알았는데 알고 보니 에겐남이더라.", "eng": "I took him for a teto guy, but he turned out to be an egen guy.", "ja": "테토남だと思ってたのに、実は에겐남だった。", "es": "Lo tomaba por un chico teto, pero resultó ser egen.", "vi": "Cứ tưởng ảnh kiểu teto, hóa ra là egen.", "de": "Ich hielt ihn für einen Teto-Typ, dabei ist er ein Egen-Typ."}]}]'::jsonb, '남성호르몬 테스토스테론(testosterone)의 축약. 여성호르몬을 딴 ‘에겐’과 짝을 이루는 성격 유형 분류로, 2021년 블로그 글에서 비슷한 분류가 처음 제시됐다는 설이 있고 2024년 3월 인스타툰으로 재구성돼 퍼진 뒤 2025년 중반 ‘테토남·에겐녀’ 형태로 크게 유행했다. 최초 출처는 확정되지 않았다.', '{"en": "Short for the hormone testosterone. It pairs with 에겐 (from estrogen) as a personality classification: a 2021 blog post is credited with an early version, an Instagram webtoon reworked it in March 2024, and the 테토남/에겐녀 labels went mainstream around mid-2025. The first source is not settled.", "ja": "男性ホルモン「テストステロン」の略。女性ホルモン由来の「에겐」と対になる性格分類で、2021年のブログ記事に原型があるとされ、2024年3月にインスタ漫画で再構成されて広まり、2025年半ばに「테토남・에겐녀」の形で大流行した。最初の出典は未確定。", "es": "Abreviatura de la hormona testosterona. Forma pareja con 에겐 (de estrógeno) como clasificación de personalidad: se atribuye una versión temprana a un blog de 2021, un webtoon de Instagram la rehízo en marzo de 2024 y las etiquetas 테토남/에겐녀 estallaron hacia mediados de 2025. La fuente original no está confirmada.", "vi": "Viết tắt của hormone testosterone. Đi cặp với 에겐 (từ estrogen) thành một cách phân loại tính cách: một bài blog năm 2021 được cho là bản đầu, webtoon Instagram dựng lại tháng 3/2024, rồi các nhãn 테토남/에겐녀 bùng lên giữa năm 2025. Nguồn đầu tiên chưa được xác định.", "de": "Kurzform des Hormons Testosteron. Es bildet mit 에겐 (von Östrogen) ein Paar als Persönlichkeitsschema: Eine frühe Fassung wird einem Blogbeitrag von 2021 zugeschrieben, ein Instagram-Webtoon arbeitete sie im März 2024 neu auf, und die Label 테토남/에겐녀 wurden Mitte 2025 zum Massentrend. Die Erstquelle ist ungeklärt."}'::jsonb, '‘테토남’, ‘테토녀’처럼 성별을 붙여 쓰고, 온라인 성향 테스트 결과를 공유하며 MBTI처럼 가볍게 쓴다. 어느 형태로 검색해도 이 항목 하나로 나온다. 다만 성격을 남녀 호르몬으로 가르는 방식이라 성 고정관념을 굳힌다는 비판도 있어, 남을 규정하기보다 자기 소개용으로 쓰는 편이 무난하다.', '{"en": "Used with a gender marker — 테토남, 테토녀 — and traded around like MBTI results from online quizzes; either form leads to this one entry. Note that sorting personality by male/female hormones draws criticism for reinforcing gender stereotypes, so it lands better as self-description than as a label for others.", "ja": "「테토남」「테토녀」のように性別を付けて使い、オンライン診断の結果をMBTIのように気軽に共有する。どちらの形で検索してもこの一項目にたどり着く。ただし性格を男女のホルモンで分ける発想は性別の固定観念を強めるという批判もあるため、他人を決めつけるより自己紹介に使うのが無難。", "es": "Se usa con marca de género — 테토남, 테토녀 — y se comparte como los resultados de MBTI en tests en línea; cualquiera de las formas lleva a esta misma entrada. Ojo: clasificar la personalidad por hormonas masculinas y femeninas recibe críticas por reforzar estereotipos de género, así que funciona mejor para describirse a uno mismo que para etiquetar a otros.", "vi": "Dùng kèm giới tính — 테토남, 테토녀 — và chia sẻ kết quả trắc nghiệm online y như MBTI; tìm dạng nào cũng ra đúng mục này. Lưu ý: chia tính cách theo hormone nam/nữ bị phê là củng cố định kiến giới, nên dùng để tự giới thiệu thì ổn hơn là gán cho người khác.", "de": "Wird mit Geschlechtsangabe benutzt — 테토남, 테토녀 — und wie MBTI-Ergebnisse aus Online-Tests herumgereicht; beide Formen führen zu diesem einen Eintrag. Achtung: Persönlichkeit nach männlichen und weiblichen Hormonen zu sortieren, steht in der Kritik, Geschlechterklischees zu verfestigen — als Selbstbeschreibung passt es besser als als Etikett für andere."}'::jsonb, array['에겐'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "“Teto” — the testosterone (bold, direct) personality type"}, {"lang": "🇯🇵 JA", "text": "テト(テストステロン型・率直で主導的なタイプ)"}, {"lang": "🇨🇳 ZH", "text": "睾酮型性格(直率主动)"}, {"lang": "🇻🇳 VI", "text": "Kiểu “testosterone” — thẳng thắn, chủ động"}, {"lang": "🇪🇸 ES", "text": "“Teto” — tipo testosterona (directo y decidido)"}, {"lang": "🇩🇪 DE", "text": "„Teto“ — der Testosteron-Typ (direkt, bestimmend)"}]'::jsonb, array['테토남','테토녀']);

commit;

